def count_squares(lines):
    # Parse the input picture into a matrix of characters
    matrix = [list(line) for line in lines]
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0

    def is_square(i, j, size):
        # Check if the top-left corner is a '+'
        if matrix[i][j] != '+':
            return False
        # Check if the rest of the square is '+'
        for x in range(size):
            for y in range(size):
                if x > 0 and y > 0:
                    # Check if the current position is '+'
                    if matrix[i + x][j + y] != '+':
                        return False
        return True

    count = 0
    # Iterate over all possible square sizes
    for size in range(2, min(rows, cols) + 1):
        for i in range(rows - size + 1):
            for j in range(cols - size + 1):
                if is_square(i, j, size):
                    count += 1

    return count

