def count_squares(lines):
    def is_corner(c):
        return c == '+'

    def is_edge(c):
        return c in '-|'

    def is_space(c):
        return c == ' '

    def is_square_corner(c):
        return is_corner(c) or is_space(c)

    def is_square_edge(c):
        return is_edge(c) or is_space(c)

    def is_square(c):
        return is_square_corner(c) and is_square_edge(c)

    def get_neighbors(i, j):
        neighbors = []
        if i > 0 and j > 0:
            neighbors.append((i-1, j-1))
        if i > 0:
            neighbors.append((i-1, j))
        if i > 0 and j < len(lines[i]) - 1:
            neighbors.append((i-1, j+1))
        if j > 0:
            neighbors.append((i, j-1))
        if j < len(lines[i]) - 1:
            neighbors.append((i, j+1))
        if i < len(lines) - 1 and j > 0:
            neighbors.append((i+1, j-1))
        if i < len(lines) - 1:
            neighbors.append((i+1, j))
        if i < len(lines) - 1 and j < len(lines[i]) - 1:
            neighbors.append((i+1, j+1))
        return neighbors

    def dfs(i, j, visited):
        if (i, j) in visited:
            return False
        visited.add((i, j))
        neighbors = get_neighbors(i, j)
        for ni, nj in neighbors:
            if lines[ni][nj] != '+':
                return False
        return True

    count = 0
    visited = set()
    for i in range(len(lines)):
        for j in range(len(lines[i])):
            if lines[i][j] == '+':
                if dfs(i, j, visited):
                    count += 1
    return count

def count_squares(lines):
    matrix = [list(line) for line in lines]
    n, m = len(matrix), len(matrix[0])
    squares = 0

    # Helper function to check if a square can be formed from a given corner
    def is_square(i, j):
        if matrix[i][j] != '+':
            return False
        # Check all sides of the square
        if i - 1 >= 0 and matrix[i-1][j] == '+':
            if j - 1 >= 0 and matrix[i-1][j-1] == '+':
                if i + 1 < n and matrix[i+1][j] == '+':
                    if j + 1 < m and matrix[i+1][j+1] == '+':
                        return True
        return False

    # Iterate through each character in the matrix
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == '+':
                # Check if the current corner can form a square
                if is_square(i, j):
                    squares += 1

    return squares

