        for corner in corners:
            x, y = corner
            for size in range(2, len(lines)):
                if is_square(x, y, size):
                    count += 1
        return count

    # Parse the input
    lines = [list(line) for line in lines]

    # Find corners
    corners = find_corners()

    # Count squares
